/* ==================== STILI MOBILE CSC PREMIUM ==================== */
@media (max-width: 1279px) {
  .header-row {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    z-index: 30;
    background: transparent;
    pointer-events: none;
  }

  .title-group {
    background: linear-gradient(180deg, rgba(22,30,42,0.96), rgba(12,18,28,0.94));
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 14px;
    padding: 12px 15px;
    max-width: 68%;
    box-shadow: 0 10px 24px rgba(0,0,0,0.35), inset 0 1px 0 rgba(255,255,255,0.03);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    pointer-events: auto;
    cursor: grab;
    user-select: none;
    position: absolute;
    top: 18px;
    left: 18px;
    z-index: 50;
  }

  .title {
    font-size: 15px;
    line-height: 1.25;
    font-weight: 800;
    letter-spacing: -0.02em;
    color: #f8fafc;
    margin: 0;
  }

  .subtitle, .sources {
    display: none !important;
  }

  .actions {
    display: flex;
    flex-direction: column;
    gap: 9px;
    align-items: flex-end;
    position: absolute;
    right: 12px;
    top: 12px;
    z-index: 40;
    pointer-events: auto;
  }

  .btn {
    background: linear-gradient(180deg, rgba(22,30,42,0.96), rgba(10,18,28,0.94));
    border: 1px solid rgba(255,255,255,0.07);
    color: #f8fafc;
    width: 50px;
    height: 50px;
    padding: 0;
    border-radius: 14px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    box-shadow: 0 8px 20px rgba(0,0,0,0.30), inset 0 1px 0 rgba(255,255,255,0.03);
    transition: transform 0.15s ease, border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
  }

  /* ==================== NASCONDI COMPLETAMENTE LE FRECCE ==================== */
  .btn.nav-btn,
  #prev-btn,
  #next-btn {
    display: none !important;
  }

  .chart-container {
    justify-content: center;
    align-items: center;
  }

  .chart-container img,
  .chart-container picture {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
    border-radius: 12px;
    box-shadow: 0 14px 36px rgba(0,0,0,0.40), 0 0 0 1px rgba(255,255,255,0.03);
  }
}

/* ==================== DESKTOP (≥ 1280px) ==================== */
@media (min-width: 1280px) {
  .actions {
    position: relative;
    right: auto;
    top: auto;
    display: flex;
    flex-direction: row;
  }

  /* Forza nascondimento freccia destra anche su desktop se non serve */
  #next-btn {
    display: none !important;
  }
}

